import type { AvatarStackProps } from "./avatar-stack.types";
import type { CSSObject } from "@emotion/react";

import { AvatarClasses } from "@components/avatar";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "AvatarStack";

// Generate child element class names for the component, should match available style slots
export const AvatarStackClasses = {
  root: "exp-textura_avatar-stack",
  reverse: "exp-textura_avatar_stack_reverse",
  xxsm: "exp-textura_avatar-stack_xxsm",
  xsm: "exp-textura_avatar-stack_xsm",
  sm: "exp-textura_avatar-stack_sm",
  md: "exp-textura_avatar-stack_md",
  lg: "exp-textura_avatar-stack_lg",
  xlg: "exp-textura_avatar-stack_xlg",
  xxlg: "exp-textura_avatar-stack_xxlg",
};

const generateStyles = (props: AvatarStackProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AvatarStackProps["styleSlots"]>(componentName, theme, variant, styleSlotsProp),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-flex",

    [`&.${AvatarStackClasses.xxsm}`]: {
      [`& > *:not(:first-of-type)`]: {
        marginInlineStart: theme.toRem(-3),
      },
      [`> .${AvatarClasses.ring}`]: {
        outlineWidth: theme.toRem(theme.border.width.sm),
      },
      ...styleSlots?.xxsm,
    },
    [`&.${AvatarStackClasses.xsm}`]: {
      [`& > *:not(:first-of-type)`]: {
        marginInlineStart: theme.toRem(-4),
      },
      [`> .${AvatarClasses.ring}`]: {
        outlineWidth: theme.toRem(theme.border.width.sm),
      },
      ...styleSlots?.xsm,
    },
    [`&.${AvatarStackClasses.sm}`]: {
      [`& > *:not(:first-of-type)`]: {
        marginInlineStart: theme.toRem(-5),
      },
      [`> .${AvatarClasses.ring}`]: {
        outlineWidth: theme.toRem(theme.border.width.md),
      },
      ...styleSlots?.sm,
    },
    [`&.${AvatarStackClasses.md}`]: {
      [`& > *:not(:first-of-type)`]: {
        marginInlineStart: theme.toRem(-5),
      },
      [`> .${AvatarClasses.ring}`]: {
        outlineWidth: theme.toRem(theme.border.width.md),
      },
      ...styleSlots?.md,
    },
    [`&.${AvatarStackClasses.lg}`]: {
      [`& > *:not(:first-of-type)`]: {
        marginInlineStart: theme.toRem(-6),
      },
      [`> .${AvatarClasses.ring}`]: {
        outlineWidth: theme.toRem(theme.border.width.md),
      },
      ...styleSlots?.lg,
    },
    [`&.${AvatarStackClasses.xlg}`]: {
      [`& > *:not(:first-of-type)`]: {
        marginInlineStart: theme.toRem(-8),
      },
      [`> .${AvatarClasses.ring}`]: {
        outlineWidth: theme.toRem(theme.border.width.lg),
      },
      ...styleSlots?.xlg,
    },
    [`&.${AvatarStackClasses.xxlg}`]: {
      [`& > *:not(:first-of-type)`]: {
        marginInlineStart: theme.toRem(-10),
      },
      [`> .${AvatarClasses.ring}`]: {
        outlineWidth: theme.toRem(theme.border.width.lg),
      },
      ...styleSlots?.xxlg,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledAvatarStack = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<AvatarStackProps>((props) => generateStyles(props));
